/**
 * fiscalWeek — Walmart fiscal calendar utilities.
 *
 * Walmart fiscal rules:
 *   • Fiscal year runs Feb 1 → Jan 31
 *   • Weeks run Saturday → Friday (weekStartDay = 6)
 *   • 13 periods per fiscal year with a 4-5-4 week pattern:
 *       Periods 1, 4, 7, 10 → 4 weeks
 *       Periods 2, 5, 8, 11 → 5 weeks
 *       Periods 3, 6, 9, 12 → 4 weeks
 *       Period 13            → 4 weeks (5 in a 53-week year)
 *   • The fiscal year starts on the Saturday closest to Feb 1
 *
 * All functions are pure and depend only on `date-fns`.
 */
import type { IFiscalWeekInfo, IWalmartWeekRange } from '../types';
/**
 * Get the Saturday that starts the Walmart fiscal year.
 *
 * Rule: The fiscal year starts on the Saturday closest to Feb 1.
 * This means the Saturday on or before Feb 4 (within the 7-day window
 * of Jan 29 through Feb 4 inclusive).
 */
export declare function getFiscalYearStart(fiscalYear: number): Date;
/**
 * Get the last day (Friday) of the fiscal year.
 */
export declare function getFiscalYearEnd(fiscalYear: number): Date;
/**
 * Get the total number of weeks in a fiscal year (52 or 53).
 */
export declare function getWeeksInFiscalYear(fiscalYear: number): number;
/**
 * Determine which Walmart fiscal year a given date falls in.
 */
export declare function getFiscalYearForDate(date: Date): number;
/**
 * Get the IFiscalWeekInfo for a given date.
 */
export declare function getFiscalWeekForDate(date: Date): IFiscalWeekInfo;
/**
 * Get all fiscal weeks for a given period in a fiscal year.
 */
export declare function getWeeksForPeriod(fiscalYear: number, periodNumber: number): IFiscalWeekInfo[];
/**
 * Get all fiscal weeks that overlap with a given calendar month.
 * Used to populate DvSelect dropdown options for a visible month.
 */
export declare function getWeeksForMonth(date: Date): IFiscalWeekInfo[];
/**
 * Build a IWalmartWeekRange from two IFiscalWeekInfo objects.
 */
export declare function buildIWalmartWeekRange(startWeekInfo: IFiscalWeekInfo, endWeekInfo: IFiscalWeekInfo): IWalmartWeekRange;
/**
 * Check if a date falls within a Walmart week range.
 */
export declare function isDateInWalmartRange(date: Date, range: IWalmartWeekRange): boolean;
/**
 * Snap a date to the full Sat-Fri fiscal week boundaries.
 * Clicking any day in Walmart mode selects the ENTIRE week.
 */
export declare function snapToFiscalWeek(date: Date): {
    start: Date;
    end: Date;
};
/**
 * Format a IFiscalWeekInfo for use as a DvSelect option label.
 * e.g., "Jan 11, 2025–Jan 17, 2025 (WK3)"
 * Supports localization by accepting a locale parameter.
 */
export declare function formatWeekOptionLabel(info: IFiscalWeekInfo, locale: string): string;
/**
 * Generate a unique ID for a fiscal week (for DvSelect option id).
 * Uses absolute week number for unique identification across the FY.
 */
export declare function getFiscalWeekId(info: IFiscalWeekInfo): string;
/**
 * Get all fiscal weeks for an entire fiscal year (52 or 53 weeks).
 * Used to populate dropdown options with the full continuous week list.
 */
export declare function getAllWeeksForFiscalYear(fiscalYear: number): IFiscalWeekInfo[];
/**
 * Get all fiscal weeks that overlap with a given date range.
 * Includes any week where the week's range intersects the target date range.
 *
 * @param startDate - Beginning of the target date range
 * @param endDate - End of the target date range
 * @returns Array of fiscal weeks that overlap the range, sorted chronologically
 */
export declare function getAllWeeksInDateRange(startDate: Date, endDate: Date): IFiscalWeekInfo[];
